<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { CloudSun, ExternalLink, Hotel, Search } from '@lucide/vue'
import type { TripRecord } from '../api/trips'
import { dateLabel, localDate, preferences } from './model'
import { bookingLink, defaultCheckout, fetchWeather, findDestinations, weatherLabel, type Destination, type Weather } from './services'
const props=defineProps<{trip:TripRecord;day:string}>()
const query=ref(''),destinations=ref<Destination[]>([]),selected=ref<Destination|null>(null),weather=ref<Weather|null>(null),loading=ref(false),error=ref('')
const destination=ref(''),checkin=ref(''),checkout=ref(''),adults=ref(1)
let request=0
watch(()=>props.trip.id,()=>{request++;query.value=props.trip.destination?.split(/[、,，/→]/)[0]||'';destinations.value=[];selected.value=null;weather.value=null;error.value='';loading.value=false;destination.value=query.value;checkin.value=props.trip.startsOn||localDate();checkout.value=defaultCheckout(checkin.value,props.trip.endsOn);adults.value=preferences(props.trip).travelers},{immediate:true})
const hotelUrl=computed(()=>bookingLink(destination.value,checkin.value,checkout.value,adults.value))
const forecast=computed(()=>{const data=weather.value;if(!data)return [];return data.daily.time.map((date,index)=>({date,code:data.daily.weather_code[index],high:data.daily.temperature_2m_max[index],low:data.daily.temperature_2m_min[index],rain:data.daily.precipitation_probability_max[index]})).filter(item=>!props.trip.startsOn||item.date>=props.trip.startsOn).filter(item=>!props.trip.endsOn||item.date<=props.trip.endsOn)})
async function search(){if(loading.value||query.value.trim().length<2)return;const current=++request;loading.value=true;error.value='';try{const rows=await findDestinations(query.value.trim());if(current!==request)return;destinations.value=rows;if(!rows.length)error.value='未找到城市，请尝试城市英文名或更完整的名称'}catch(cause){if(current===request)error.value=cause instanceof Error?cause.message:'城市查询失败'}finally{if(current===request)loading.value=false}}
async function select(city:Destination){const current=++request;loading.value=true;error.value='';selected.value=city;weather.value=null;destinations.value=[];try{const result=await fetchWeather(city.latitude,city.longitude);if(current===request)weather.value=result}catch(cause){if(current===request)error.value=cause instanceof Error?cause.message:'天气获取失败'}finally{if(current===request)loading.value=false}}
</script>
<template>
  <section class="tw-compact-card tw-weather-card"><header><h3><CloudSun :size="17"/>目的地天气</h3></header><p>主动查询城市天气；只显示未来预报范围内的数据。</p><form class="tw-service-search" @submit.prevent="search"><input v-model="query" maxlength="120" placeholder="城市名称" aria-label="天气城市"/><button class="tw-icon" :disabled="loading||query.trim().length<2" aria-label="查询天气城市"><Search :size="16"/></button></form><p class="tw-hint">查询文字发送到 Open-Meteo；选中城市后才查询天气。</p><div v-if="destinations.length" class="tw-city-results"><button v-for="city in destinations" :key="city.id" :disabled="loading" @click="select(city)"><b>{{ city.name }}</b><small>{{ [city.admin1,city.country].filter(Boolean).join(' · ') }}</small></button></div><p v-if="loading" role="status">正在获取数据…</p><p v-if="error" class="tw-error" role="alert">{{ error }}</p><template v-if="weather"><div class="tw-weather-current"><span>{{ selected?.name }}<small>{{ weather.timezone }}</small></span><b>{{ weather.current.temperature_2m??'—' }}°<small>{{ weatherLabel(weather.current.weather_code) }}</small></b></div><div v-if="forecast.length" class="tw-weather-days"><article v-for="item in forecast.slice(0,7)" :key="item.date" :class="{selected:item.date===day}"><b>{{ dateLabel(item.date,{month:'numeric',day:'numeric'}) }}</b><span>{{ weatherLabel(item.code) }}</span><span>{{ item.low??'—' }}° / {{ item.high??'—' }}°</span><small>降水 {{ item.rain==null?'—':item.rain+'%' }}</small></article></div><p v-else class="tw-hint">这趟旅行不在当前预报范围内，请临近出行时再次查询。</p><p class="tw-hint">最多展示行程中前 7 个有预报的日期；来源 <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · 更新 {{ new Date(weather.fetchedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) }}，预报可能变化。</p><button class="tw-text" :disabled="loading" @click="selected&&select(selected)">重新查询所选城市</button></template></section>
  <section class="tw-compact-card tw-hotel-card"><header><h3><Hotel :size="17"/>找一处落脚点</h3></header><p>带上目的地、入住日期和成人数，前往平台查价与预订。</p><div class="tw-field"><label for="stay-destination">住宿目的地</label><input id="stay-destination" v-model="destination" maxlength="180"/></div><div class="tw-form-grid"><div class="tw-field"><label for="stay-checkin">入住</label><input id="stay-checkin" v-model="checkin" type="date"/></div><div class="tw-field"><label for="stay-checkout">退房</label><input id="stay-checkout" v-model="checkout" type="date" :min="checkin"/></div></div><div class="tw-field"><label for="stay-adults">成人数（含儿童请到平台调整）</label><input id="stay-adults" v-model.number="adults" type="number" min="1" max="30"/></div><a v-if="hotelUrl" class="tw-button secondary" :href="hotelUrl" target="_blank" rel="noopener noreferrer">前往 Booking.com<ExternalLink :size="13"/></a><p v-else class="tw-error">请填写目的地、有效日期和成人数；退房需晚于入住。</p><p class="tw-hint">目的地、日期和成人数只在点击后传给平台。房价、房量、付款、订单与取消均以平台为准；本应用不会代下单。</p></section>
</template>
